//  КАСТОМНЫЙ ДРОПДАУН СКАНЕРА + TOOLTIP
// ═══════════════════════════════════════════════════

// Единственный элемент — карточка характеристик 
const _tip = document.createElement('div');
_tip.style.cssText = [
  'position:fixed',
  'z-index:99999',
  'top:50%',
  'left:50%',
  'transform:translate(-50%,-50%)',
  'background:#0D0E1A',
  'color:#fff',
  'border-radius:14px',
  'width:360px',
  'max-width:92vw',
  'max-height:78vh',
  'display:flex',
  'flex-direction:column',
  'box-shadow:0 16px 48px rgba(0,0,0,.7)',
  'pointer-events:none',   // ВАЖНО: мышь насквозь
  'opacity:0',
  'transition:opacity .15s',
  'border:1px solid rgba(255,255,255,.14)',
  'font-size:13px',
  'line-height:1.55',
  'font-family:Inter,system-ui,sans-serif',
  'cursor:default',
].join(';');
document.body.appendChild(_tip);

let _hoverTimer = null;

function _tipShow(key) {
  const items = SCANNER_SPECS[key];
  if (!items || !items.length) return;

  const sections = {};
  items.forEach(({k,v,s}) => { if(!sections[s]) sections[s]=[]; sections[s].push({k,v}); });

  let bodyHTML = '';
  for (const [sec, rows] of Object.entries(sections)) {
    bodyHTML += `<div style="color:rgba(255,255,255,.4);font-size:10px;text-transform:uppercase;letter-spacing:.7px;margin:12px 0 5px">${sec}</div>`;
    rows.forEach(({k,v}) => {
      bodyHTML += `<div style="display:flex;gap:10px;margin-bottom:5px">
        <span style="color:rgba(255,255,255,.5);min-width:110px;flex-shrink:0;font-size:11.5px">${k}</span>
        <span style="font-weight:500">${v}</span>
      </div>`;
    });
  }

  _tip.innerHTML = `
    <div style="padding:14px 16px 12px;border-bottom:1px solid rgba(255,255,255,.1);flex-shrink:0">
      <span style="font-size:15px;font-weight:700;color:#60A5FA">${key}</span>
    </div>
    <div style="padding:4px 16px 16px;overflow-y:auto;flex:1">${bodyHTML}</div>
  `;
  _tip.style.opacity = '1';
}

function _tipHide() {
  clearTimeout(_hoverTimer);
  _hoverTimer = null;
  _tip.style.opacity = '0';
}

// Заполнить список опций
function buildScannerDropdown(vals) {
  const list = document.getElementById('scanner-options');
  if (!list) return;
  list.innerHTML = '';

  const allItem = document.createElement('div');
  allItem.className = 'scanner-opt';
  allItem.dataset.value = '';
  allItem.textContent = 'Любой сканер';
  allItem.onclick = () => _selectScanner('', 'Любой сканер');
  list.appendChild(allItem);

  vals.forEach(val => {
    const item = document.createElement('div');
    item.className = 'scanner-opt';
    item.dataset.value = val;
    item.textContent = val;
    item.onclick = () => { _tipHide(); _selectScanner(val, val); };

    item.addEventListener('mouseenter', () => {
      clearTimeout(_hoverTimer);
      _hoverTimer = setTimeout(() => _tipShow(val), 300);
    });
    item.addEventListener('mouseleave', () => {
      clearTimeout(_hoverTimer);
      _hoverTimer = null;
      _tip.style.opacity = '0';
    });

    list.appendChild(item);
  });

  const cur = (document.getElementById('scanner-select') || {}).value || '';
  list.querySelectorAll('.scanner-opt').forEach(o => o.classList.toggle('active', o.dataset.value === cur));
}

function toggleScannerDropdown() {
  const list = document.getElementById('scanner-options');
  if (!list) return;
  const isOpen = list.style.display !== 'none';
  if (isOpen) {
    list.style.display = 'none';
    _tipHide();
    return;
  }
  if (list.children.length === 0 && typeof SKU_DB !== 'undefined' && SKU_DB.length) {
    const vals = Array.from(new Set(SKU_DB.map(s=>s.scanner).filter(Boolean))).sort();
    buildScannerDropdown(vals);
  }
  list.style.display = 'block';
}

function _selectScanner(value, label) {
  const input = document.getElementById('scanner-select');
  if (input) input.value = value;
  const disp = document.getElementById('scanner-display-text');
  if (disp) disp.textContent = label;
  const list = document.getElementById('scanner-options');
  if (list) {
    list.style.display = 'none';
    list.querySelectorAll('.scanner-opt').forEach(o => o.classList.toggle('active', o.dataset.value === value));
  }
  updateMemoryOptions();
  filterSKU();
}

// Закрыть дропдаун при клике снаружи
document.addEventListener('click', e => {
  const dd = document.getElementById('scanner-dropdown');
  if (dd && !dd.contains(e.target)) {
    const list = document.getElementById('scanner-options');
    if (list) { list.style.display = 'none'; _tipHide(); }
  }
});

