function getBadges(sku){const badges=[];if(parseFloat(sku.android)>=13){const androidVer=parseFloat(sku.android);const androidBadgeText=androidVer>=16?`Android ${Math.floor(androidVer)} Ready`:androidVer<14?`Android ${Math.floor(androidVer)} Ready`:t('badge_android_ready');badges.push({cls:'android-ready',text:androidBadgeText});}if(ENTERPRISE_MODELS.includes(sku.model))badges.push({cls:'enterprise',text:t('badge_enterprise')});const ip=IP_RATINGS[sku.model];if(ip)badges.push({cls:'ip-badge',text:ip});if(sku.lte==='YES')badges.push({cls:'lte',text:t('badge_4g')});if(sku.frost==='YES'&&sku.model!=='SL20'&&sku.model!=='SL20P'&&sku.model!=='SL20K')badges.push({cls:'frozen',text:t('badge_frozen')});if(sku.model==='SM24')badges.push({cls:'new-coming',text:'★ NEW'});if(sku.model==='SM25')badges.push({cls:'new-coming',text:'★ NEW'});return badges;}
function renderResults(list){
  const container=$('results-container');
  if(!list.length){
    container.innerHTML=`<div class="no-results"><p>${t('no_results_found')}</p></div>`;
    return;
  }
  container.innerHTML='';
  const frag=$f();
  renderResultCards(list,frag);
  container.appendChild(frag);
  // Animate cards in
  requestAnimationFrame(() => {
    container.querySelectorAll('.result-card').forEach((card, i) => {
      card.style.opacity = '0';
      card.style.transform = 'translateY(14px)';
      card.style.transition = 'none';
      requestAnimationFrame(() => {
        card.style.transition = `opacity .22s ease ${i * 30}ms, transform .22s ease ${i * 30}ms`;
        card.style.opacity = '1';
        card.style.transform = 'translateY(0)';
      });
    });
  });
}
