function toggleComparison(skuCode){const i=comparisonList.indexOf(skuCode);if(i>-1)comparisonList.splice(i,1);else{if(comparisonList.length>=4){showToast('Максимум 4 SKU');return;}comparisonList.push(skuCode);}$('comparison-count').textContent=comparisonList.length;const hasItems=comparisonList.length>0;$('btn-float-compare').classList.toggle('visible',hasItems);const clrBtn=$('btn-float-clear-compare');if(clrBtn)clrBtn.classList.toggle('visible',hasItems);filterSKU();}
