const OCS_API = 'https://ocs.m3-mobile.ru';
let ocsData = [];
let ocsLoaded = false;

function openOcsModal() {
  document.getElementById('ocs-modal').classList.add('open');
  document.body.style.overflow = 'hidden';
  if (!ocsLoaded) loadOcsData();
}

function closeOcsModal() {
  document.getElementById('ocs-modal').classList.remove('open');
  document.body.style.overflow = '';
}

function closeOcsOnBackdrop(e) {
  if (e.target === document.getElementById('ocs-modal')) closeOcsModal();
}

async function loadOcsData() {
  const body = document.getElementById('ocs-body');
  body.innerHTML = '<div class="treolan-loading">⏳ Загружаем склад OCS...</div>';
  document.getElementById('ocs-updated').textContent = 'Загрузка...';
  try {
    const res = await fetch(OCS_API + '/api/m3');
    if (!res.ok) throw new Error('Ошибка ' + res.status);
    const json = await res.json();
    ocsData = json.items || [];
    window.OCS_DATA = ocsData;
    ocsLoaded = true;
    window.ocsLoaded = true;
    const updated = new Date().toLocaleString('ru-RU');
    document.getElementById('ocs-updated').textContent = `Обновлено: ${updated} · ${ocsData.length} позиций`;
    _loadedAt.ocs = Date.now(); _startAutoRefresh('ocs', loadOcsData, 5);
    document.getElementById('ocs-footer-info').textContent = `Всего: ${ocsData.length} позиций`;
    filterOcsTable();
  } catch (e) {
    body.innerHTML = `<div class="treolan-error">❌ ${e.message}</div>`;
    document.getElementById('ocs-updated').textContent = 'Ошибка загрузки';
  }
}

function filterOcsTable(sortCol) {
  const q = document.getElementById('ocs-search').value.toLowerCase();
  const avail = document.getElementById('ocs-avail-filter').value;
  if (!window._oSort) window._oSort = {col: null, dir: 1};
  if (sortCol !== undefined) {
    window._oSort = {col: sortCol, dir: sortCol === window._oSort.col ? -window._oSort.dir : 1};
  }

  let filtered = ocsData.filter(item => {
    const articul = (item.partNumber || item.itemId || '').toLowerCase();
    const name = (item.itemNameRus || item.itemName || '').toLowerCase();
    if (q && !articul.includes(q) && !name.includes(q)) return false;
    const stockQty = (item.stock || []).reduce((s,l) => s+(l.quantity||0), 0);
    const transitQty = (item.transit || []).reduce((s,l) => s+(l.quantity||0), 0);
    if (avail === 'avail' && stockQty <= 0) return false;
    if (avail === 'transit' && transitQty <= 0) return false;
    if (avail === 'none' && (stockQty > 0 || transitQty > 0)) return false;
    return true;
  });

  // Add computed fields for sorting
  filtered = filtered.map(item => ({
    ...item,
    _articul: item.partNumber || item.itemId || '',
    _name: item.itemNameRus || item.itemName || '',
    _stock: (item.stock || []).reduce((s,l) => s+(l.quantity||0), 0),
    _transit: (item.transit || []).reduce((s,l) => s+(l.quantity||0), 0),
  }));

  if (window._oSort.col) {
    filtered.sort((a,b) => {
      let va = a[window._oSort.col]||0, vb = b[window._oSort.col]||0;
      if (typeof va === 'string') return va.localeCompare(vb,'ru') * window._oSort.dir;
      return (va - vb) * window._oSort.dir;
    });
  }

  const arrow = (col) => window._oSort.col === col ? (window._oSort.dir===1?' ↑':' ↓') : '';
  const thS = 'cursor:pointer;user-select:none';

  const rows = filtered.map(item => {
    const stockQty = item._stock;
    const transitQty = item._transit;
    const transitDate = (item.transit||[]).map(l=>l.deliveryDate).filter(Boolean)[0]||'';
    return `<tr>
      <td><div class="t-articul">${item._articul}</div></td>
      <td><div class="t-name">${item._name}</div></td>
      <td>${stockQty>0?'<span class="t-badge-avail">В наличии</span>':'<span class="t-badge-noavail">Нет</span>'}</td>
      <td><span class="t-stock${stockQty<=0?' zero':''}">${stockQty>=999?'много':stockQty}</span></td>
      <td><span class="t-transit${transitQty<=0?' zero':''}">${transitQty>=999?'много':(transitQty||'—')}</span>${transitDate?`<div class="t-date">${transitDate}</div>`:''}</td>
    </tr>`;
  }).join('');

  document.getElementById('ocs-stats').textContent = `Показано: ${filtered.length}`;
  document.getElementById('ocs-body').innerHTML = rows.length
    ? `<table class="treolan-table"><thead><tr>
        <th style="${thS}" onclick="filterOcsTable('_articul')">Артикул${arrow('_articul')}</th>
        <th style="${thS}" onclick="filterOcsTable('_name')">Наименование${arrow('_name')}</th>
        <th>Наличие</th>
        <th style="${thS}" onclick="filterOcsTable('_stock')">Склад${arrow('_stock')}</th>
        <th style="${thS}" onclick="filterOcsTable('_transit')">Транзит${arrow('_transit')}</th>
      </tr></thead><tbody>${rows}</tbody></table>`
    : '<div class="treolan-loading">😶 Ничего не найдено</div>';
}


document.addEventListener('keydown', e => {
  if (e.key === 'Escape') closeOcsModal();
});


// ═══════════════════════════════════════════════════
//  М3 STOCK MODAL
// ═══════════════════════════════════════════════════
const M3_STOCK_CSV = 'https://docs.google.com/spreadsheets/d/e/2PACX-1vRTapyh4HL6l3S7RzTA0k4ZpT6laCs7R67b3hVmh2dXuuCOuPYx9VztyGMiNHxC2fwK-KPlfZouVsVY/pub?output=csv';
let m3StockData = [];
let m3StockLoaded = false;

function openM3StockModal() {
  document.getElementById('m3stock-modal').classList.add('open');
  document.body.style.overflow = 'hidden';
  if (!m3StockLoaded) loadM3StockData();
}

function closeM3StockModal() {
  document.getElementById('m3stock-modal').classList.remove('open');
  document.body.style.overflow = '';
}

function closeM3StockOnBackdrop(e) {
  if (e.target === document.getElementById('m3stock-modal')) closeM3StockModal();
}

async function loadM3StockData() {
  const body = document.getElementById('m3stock-body');
  body.innerHTML = '<div class="treolan-loading">⏳ Загружаем склад M3...</div>';
  document.getElementById('m3stock-updated').textContent = 'Загрузка...';
  try {
    const res = await fetch(M3_STOCK_CSV);
    if (!res.ok) throw new Error('Ошибка ' + res.status);
    const text = await res.text();
    const rows = text.trim().split('\n');
    const headers = rows[0].split(',').map(h => h.trim().replace(/^"|"$/g, '').toLowerCase());
    
    m3StockData = rows.slice(1).map(row => {
      // Handle quoted fields with commas
      const fields = [];
      let current = '';
      let inQuotes = false;
      for (const char of row) {
        if (char === '"') { inQuotes = !inQuotes; }
        else if (char === ',' && !inQuotes) { fields.push(current.trim()); current = ''; }
        else { current += char; }
      }
      fields.push(current.trim());
      
      const obj = {};
      headers.forEach((h, i) => obj[h] = (fields[i] || '').replace(/^"|"$/g, ''));
      return obj;
    }).filter(row => Object.values(row).some(v => v));

    m3StockLoaded = true;
    window.M3_STOCK_DATA = m3StockData;
    window.m3StockLoaded = true;
    const updated = new Date().toLocaleString('ru-RU');
    document.getElementById('m3stock-updated').textContent = `Обновлено: ${updated} · ${m3StockData.length} позиций`;
    _loadedAt.m3 = Date.now(); _startAutoRefresh('m3', () => { m3StockLoaded=false; loadM3StockData(); }, 10);
    document.getElementById('m3stock-footer-info').textContent = `Всего: ${m3StockData.length} позиций`;
    
    // Store headers for dynamic rendering
    window._m3StockHeaders = headers;
    filterM3StockTable();
  } catch (e) {
    body.innerHTML = `<div class="treolan-error">❌ ${e.message}</div>`;
    document.getElementById('m3stock-updated').textContent = 'Ошибка загрузки';
  }
}

function filterM3StockTable() {
  const q = document.getElementById('m3stock-search').value.toLowerCase();
  const avail = document.getElementById('m3stock-avail-filter').value;
  const headers = window._m3StockHeaders || [];
  
  // Detect key columns by common names
  const articulKey = headers.find(h => /артикул|sku|artic|part/i.test(h)) || headers[0];
  const nameKey = headers.find(h => /наимен|name|назван/i.test(h)) || headers[1];
  const stockKey = headers.find(h => /остат|склад|stock|наличи|кол/i.test(h)) || headers[2];

  let filtered = m3StockData.filter(item => {
    const articul = (item[articulKey] || '').toLowerCase();
    const name = (item[nameKey] || '').toLowerCase();
    if (q && !articul.includes(q) && !name.includes(q)) return false;
    
    const qty = parseInt(item[stockKey]) || 0;
    if (avail === 'avail' && qty <= 0) return false;
    if (avail === 'none' && qty > 0) return false;
    return true;
  });

  document.getElementById('m3stock-stats').textContent = `Показано: ${filtered.length}`;

  if (!filtered.length) {
    document.getElementById('m3stock-body').innerHTML = '<div class="treolan-loading">😶 Ничего не найдено</div>';
    return;
  }

  // Build table with all columns
  const thead = headers.map(h => `<th>${h}</th>`).join('');
  const tbody = filtered.map(item => {
    const cells = headers.map(h => {
      const val = item[h] || '';
      const num = parseInt(val);
      if (h === stockKey && !isNaN(num)) {
        return `<td><span class="t-stock${num <= 0 ? ' zero' : ''}">${num >= 999 ? 'много' : num}</span></td>`;
      }
      if (h === articulKey) return `<td><div class="t-articul">${val}</div></td>`;
      if (h === nameKey) return `<td><div class="t-name">${val}</div></td>`;
      return `<td>${val}</td>`;
    }).join('');
    return `<tr>${cells}</tr>`;
  }).join('');

  document.getElementById('m3stock-body').innerHTML = 
    `<table class="treolan-table"><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>`;
}

document.addEventListener('keydown', e => {
  if (e.key === 'Escape') { closeM3StockModal(); closeOcsModal(); }
});


// ═══════════════════════════════════════════════════
//  EXCEL EXPORT
// ═══════════════════════════════════════════════════
function exportToExcel(data, headers, filename) {
  if (!data || !data.length) return;

  // Build CSV with BOM for correct encoding in Excel
  const bom = '\uFEFF';
  const sep = ';';
  const headerRow = headers.map(h => `"${h}"`).join(sep);
  const rows = data.map(row =>
    headers.map(h => {
      const val = String(row[h] !== undefined ? row[h] : '').replace(/"/g, '""');
      return `"${val}"`;
    }).join(sep)
  );
  const csv = bom + [headerRow, ...rows].join('\n');

  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename + '_' + new Date().toISOString().slice(0,10) + '.csv';
  a.click();
  URL.revokeObjectURL(url);
}

function exportTreolan() {
  const headers = ['Артикул', 'Наименование', 'Наличие', 'Склад', 'Транзит', 'Дата транзита'];
  const rows = treolanData.map(item => ({
    'Артикул': item.articul || '',
    'Наименование': item.name || '',
    'Наличие': item.stock > 0 ? 'В наличии' : 'Нет',
    'Склад': item.stock >= 999 ? 'много' : (item.stock || 0),
    'Транзит': item.transit >= 999 ? 'много' : (item.transit || 0),
    'Дата транзита': item.transitDate || '',
  }));
  exportToExcel(rows, headers, 'Сток_Treolan_M3Mobile');
}

function exportOcs() {
  const headers = ['Артикул', 'Наименование', 'Наличие', 'Склад', 'Транзит', 'Дата транзита'];
  const rows = ocsData.map(item => {
    const stockQty = (item.stock || []).reduce((s, l) => s + (l.quantity || 0), 0);
    const transitQty = (item.transit || []).reduce((s, l) => s + (l.quantity || 0), 0);
    const transitDate = (item.transit || []).map(l => l.deliveryDate).filter(Boolean)[0] || '';
    return {
      'Артикул': item.partNumber || item.itemId || '',
      'Наименование': item.itemNameRus || item.itemName || '',
      'Наличие': stockQty > 0 ? 'В наличии' : 'Нет',
      'Склад': stockQty >= 999 ? 'много' : stockQty,
      'Транзит': transitQty >= 999 ? 'много' : transitQty,
      'Дата транзита': transitDate,
    };
  });
  exportToExcel(rows, headers, 'Сток_OCS_M3Mobile');
}

function exportM3Stock() {
  const headers = window._m3StockHeaders || [];
  exportToExcel(m3StockData, headers, 'Сток_M3Mobile');
}


// ═══════════════════════════════════════════════════
//  АВТООБНОВЛЕНИЕ И ИНДИКАТОР СВЕЖЕСТИ ДАННЫХ
// ═══════════════════════════════════════════════════
const _autoRefreshIntervals = {};

function _startAutoRefresh(modalName, loadFn, intervalMin) {
  _stopAutoRefresh(modalName);
  _autoRefreshIntervals[modalName] = setInterval(() => {
    loadFn(true); // silent refresh
  }, intervalMin * 60 * 1000);
}

function _stopAutoRefresh(modalName) {
  if (_autoRefreshIntervals[modalName]) {
    clearInterval(_autoRefreshIntervals[modalName]);
    delete _autoRefreshIntervals[modalName];
  }
}

function _updateFreshness(elId, loadedAt) {
  const el = document.getElementById(elId);
  if (!el) return;
  const diff = Math.round((Date.now() - loadedAt) / 1000);
  let text = 'только что';
  if (diff >= 60) text = `${Math.floor(diff/60)} мин назад`;
  if (diff >= 3600) text = `${Math.floor(diff/3600)} ч назад`;
  el.textContent = `Обновлено: ${text}`;
}

// Track load times
const _loadedAt = {};

// Patch modal close to stop auto-refresh
const _origCloseTreolan = window.closeTreolanModal;
const _origCloseOcs = window.closeOcsModal;
const _origCloseM3 = window.closeM3StockModal;

// Freshness ticker — updates every 30s
setInterval(() => {
  if (_loadedAt.treolan) _updateFreshness('treolan-freshness', _loadedAt.treolan);
  if (_loadedAt.ocs) _updateFreshness('ocs-freshness', _loadedAt.ocs);
  if (_loadedAt.m3) _updateFreshness('m3-freshness', _loadedAt.m3);
}, 30000);

// ═══════════════════════════════════════════════════
//  СВОДНЫЙ СТОК — все три дистрибьютора
// ═══════════════════════════════════════════════════

let combinedData = [];
let combinedLoaded = false;

function openCombinedModal() {
  const modal = document.getElementById('combined-modal');
  modal.style.display = 'flex';
  document.body.style.overflow = 'hidden';
  loadCombinedData();
}

function closeCombinedModal() {
  document.getElementById('combined-modal').style.display = 'none';
  document.body.style.overflow = '';
  _stopAutoRefresh('combined');
}

function closeCombinedOnBackdrop(e) {
  if (e.target === document.getElementById('combined-modal')) closeCombinedModal();
}

async function loadCombinedData() {
  const body = document.getElementById('combined-body');
  body.innerHTML = '<div class="treolan-loading">⏳ Загружаем данные всех дистрибьюторов...</div>';

  // Load all three in parallel
  const results = await Promise.allSettled([
    _fetchTreolan(),
    _fetchOcs(),
    _fetchM3Stock()
  ]);

  const treolanItems = results[0].status === 'fulfilled' ? results[0].value : [];
  const ocsItems     = results[1].status === 'fulfilled' ? results[1].value : [];
  const m3Items      = results[2].status === 'fulfilled' ? results[2].value : [];

  // Build unified map by articul (exact match first, then fuzzy name match)
  const map = new Map(); // key: normalized articul

  const norm = s => (s||'').trim().toUpperCase().replace(/[\s\-\/]/g,'');

  // Add Treolan items
  treolanItems.forEach(item => {
    const key = norm(item.articul);
    if (!key) return;
    if (!map.has(key)) map.set(key, {
      articul: item.articul,
      name: item.name || '',
      treolan_stock: 0, treolan_transit: 0,
      ocs_stock: 0, ocs_transit: 0,
      m3_stock: 0,
    });
    const r = map.get(key);
    r.treolan_stock = item.stock || 0;
    r.treolan_transit = item.transit || 0;
  });

  // Add OCS items
  ocsItems.forEach(item => {
    const articul = item.partNumber || item.itemId || '';
    const key = norm(articul);
    if (!key) return;
    const stockQty = (item.stock||[]).reduce((s,l)=>s+(l.quantity||0),0);
    const transitQty = (item.transit||[]).reduce((s,l)=>s+(l.quantity||0),0);
    if (map.has(key)) {
      map.get(key).ocs_stock = stockQty;
      map.get(key).ocs_transit = transitQty;
    } else {
      map.set(key, {
        articul,
        name: item.itemNameRus || item.itemName || '',
        treolan_stock: 0, treolan_transit: 0,
        ocs_stock: stockQty, ocs_transit: transitQty,
        m3_stock: 0,
      });
    }
  });

  // Add M3 items
  m3Items.forEach(item => {
    const articulVal = item['артикул'] || item['sku'] || item['articul'] || Object.values(item)[0] || '';
    const key = norm(articulVal);
    if (!key) return;
    const stockVal = parseInt(item['остаток'] || item['stock'] || item['наличие'] || 0) || 0;
    if (map.has(key)) {
      map.get(key).m3_stock = stockVal;
    } else {
      map.set(key, {
        articul: articulVal,
        name: item['наименование'] || item['name'] || '',
        treolan_stock: 0, treolan_transit: 0,
        ocs_stock: 0, ocs_transit: 0,
        m3_stock: stockVal,
      });
    }
  });

  combinedData = Array.from(map.values());
  combinedLoaded = true;

  const total = combinedData.length;
  const withStock = combinedData.filter(r => r.treolan_stock > 0 || r.ocs_stock > 0 || r.m3_stock > 0).length;
  document.getElementById('combined-footer-info').textContent =
    `Всего позиций: ${total} · С наличием: ${withStock}`;
  document.getElementById('combined-freshness').textContent =
    `Treolan: ${treolanItems.length} · OCS: ${ocsItems.length} · M3: ${m3Items.length}`;
  _loadedAt.combined = Date.now();
  _startAutoRefresh('combined', loadCombinedData, 5);

  filterCombinedTable();
}

// Fetch helpers that use cached data if available
async function _fetchTreolan() {
  if (treolanLoaded && treolanData.length) return treolanData;
  const res = await fetch(TREOLAN_API + '/api/catalog');
  const json = await res.json();
  treolanData = (json.items || []).filter(item => item.vendor === 'M3 Mobile');
  treolanLoaded = true;
  return treolanData;
}

async function _fetchOcs() {
  if (ocsLoaded && ocsData.length) return ocsData;
  const res = await fetch(OCS_API + '/api/m3');
  const json = await res.json();
  ocsData = json.items || [];
  window.OCS_DATA = ocsData;
  ocsLoaded = true;
  window.ocsLoaded = true;
  return ocsData;
}

async function _fetchM3Stock() {
  if (m3StockLoaded && m3StockData.length) return m3StockData;
  const res = await fetch(M3_STOCK_CSV);
  const text = await res.text();
  const rows = text.trim().split('\n');
  const headers = rows[0].split(',').map(h => h.trim().replace(/^"|"$/g,'').toLowerCase());
  m3StockData = rows.slice(1).map(row => {
    const vals = row.split(',').map(v => v.trim().replace(/^"|"$/g,''));
    const obj = {};
    headers.forEach((h,i) => obj[h] = vals[i]||'');
    return obj;
  }).filter(r => Object.values(r).some(v=>v));
  m3StockLoaded = true;
  return m3StockData;
}

function filterCombinedTable(sortCol) {
  if (!combinedLoaded) return;
  const q = document.getElementById('combined-search').value.toLowerCase();
  const avail = document.getElementById('combined-avail-filter').value;
  if (!window._cSort) window._cSort = {col: 'total', dir: -1};
  if (sortCol !== undefined) {
    window._cSort = {col: sortCol, dir: sortCol === window._cSort.col ? -window._cSort.dir : 1};
  }

  let filtered = combinedData.map(r => ({
    ...r,
    total: r.treolan_stock + r.ocs_stock + r.m3_stock,
  })).filter(r => {
    if (q && !(r.articul||'').toLowerCase().includes(q) && !(r.name||'').toLowerCase().includes(q)) return false;
    if (avail === 'avail' && r.total <= 0) return false;
    if (avail === 'all3' && (r.treolan_stock <= 0 || r.ocs_stock <= 0 || r.m3_stock <= 0)) return false;
    return true;
  });

  if (window._cSort.col) {
    filtered.sort((a,b) => {
      let va = a[window._cSort.col]||0, vb = b[window._cSort.col]||0;
      if (typeof va === 'string') return va.localeCompare(vb,'ru') * window._cSort.dir;
      return (va-vb) * window._cSort.dir;
    });
  }

  document.getElementById('combined-stats').textContent = `Показано: ${filtered.length} позиций`;

  const arrow = col => window._cSort.col===col ? (window._cSort.dir===1?' ↑':' ↓') : '';
  const thS = 'cursor:pointer;user-select:none';
  const qty = (n, isTransit) => {
    if (n <= 0) return '<span style="opacity:.3">—</span>';
    const cls = isTransit ? 'color:#f59e0b' : 'color:#22c55e';
    const val = n >= 999 ? 'много' : n;
    return `<span style="font-weight:700;${cls}">${val}</span>`;
  };
  const rows = filtered.map(r => {
    const hasAny = r.total > 0;
    return `<tr style="${hasAny?'':'opacity:.45'}">
      <td><div class="t-articul">${r.articul}</div></td>
      <td><div class="t-name" style="max-width:220px">${r.name}</div></td>
      <td style="text-align:center">${qty(r.treolan_stock,false)}${r.treolan_transit>0?`<br><span style="font-size:10px;color:#f59e0b">+${r.treolan_transit>=999?'много':r.treolan_transit} транзит</span>`:''}</td>
      <td style="text-align:center">${qty(r.ocs_stock,false)}${r.ocs_transit>0?`<br><span style="font-size:10px;color:#f59e0b">+${r.ocs_transit>=999?'много':r.ocs_transit} транзит</span>`:''}</td>
      <td style="text-align:center">${qty(r.m3_stock,false)}</td>
      <td style="text-align:center;font-weight:700">${r.total>0?`<span style="color:#60A5FA">${r.total>=999?'много':r.total}</span>`:'<span style="opacity:.3">—</span>'}</td>
    </tr>`;
  }).join('');

  document.getElementById('combined-body').innerHTML = filtered.length
    ? `<table class="treolan-table" style="min-width:700px"><thead><tr>
        <th style="${thS}" onclick="filterCombinedTable('articul')">Артикул${arrow('articul')}</th>
        <th style="${thS}" onclick="filterCombinedTable('name')">Наименование${arrow('name')}</th>
        <th style="${thS};text-align:center;background:rgba(99,102,241,.15)" onclick="filterCombinedTable('treolan_stock')">Treolan${arrow('treolan_stock')}</th>
        <th style="${thS};text-align:center;background:rgba(16,185,129,.15)" onclick="filterCombinedTable('ocs_stock')">OCS${arrow('ocs_stock')}</th>
        <th style="${thS};text-align:center;background:rgba(245,158,11,.15)" onclick="filterCombinedTable('m3_stock')">M3 Сток${arrow('m3_stock')}</th>
        <th style="${thS};text-align:center" onclick="filterCombinedTable('total')">Итого${arrow('total')}</th>
      </tr></thead><tbody>${rows}</tbody></table>`
    : '<div class="treolan-loading">😔 Ничего не найдено</div>';
}

function exportCombined() {
  const headers = ['Артикул','Наименование','Treolan склад','Treolan транзит','OCS склад','OCS транзит','M3 Сток','Итого'];
  const rows = combinedData.map(r => ({
    'Артикул': r.articul,
    'Наименование': r.name,
    'Treolan склад': r.treolan_stock||0,
    'Treolan транзит': r.treolan_transit||0,
    'OCS склад': r.ocs_stock||0,
    'OCS транзит': r.ocs_transit||0,
    'M3 Сток': r.m3_stock||0,
    'Итого': (r.treolan_stock||0)+(r.ocs_stock||0)+(r.m3_stock||0),
  }));
  exportToExcel(rows, headers, 'Сводный_сток_M3Mobile');
}

document.addEventListener('keydown', e => { if (e.key === 'Escape') closeCombinedModal(); });


// ═══════════════════════════════════════════════════
//  MOBILE FILTER DRAWER
// ═══════════════════════════════════════════════════

function openFilterDrawer() {
  // Clone sidebar filters into drawer content
  const sidebar = document.querySelector('.filters-sidebar');
  const drawerContent = document.getElementById('drawer-filters-content');
  if (sidebar && drawerContent) {
    // Copy all filter groups (excluding reset button and title)
    drawerContent.innerHTML = '';
    sidebar.querySelectorAll('.filter-group, .filter-section, .filter-divider').forEach(el => {
      drawerContent.appendChild(el.cloneNode(true));
    });
    // Also clone scanner dropdown specifically
    _syncDrawerScanner();
  }

  document.getElementById('drawer-backdrop').style.display = 'block';
  requestAnimationFrame(() => {
    document.getElementById('filter-drawer').classList.add('open');
  });
  document.body.style.overflow = 'hidden';
}

function closeFilterDrawer() {
  document.getElementById('filter-drawer').classList.remove('open');
  setTimeout(() => {
    document.getElementById('drawer-backdrop').style.display = 'none';
    document.body.style.overflow = '';
  }, 300);
}

function _syncDrawerScanner() {
  // Inject live scanner dropdown into drawer
  const drawerContent = document.getElementById('drawer-filters-content');
  if (!drawerContent) return;

  // Find the scanner group placeholder in drawer and replace with live widget
  const scannerGroup = drawerContent.querySelector('.filter-group');
  if (!scannerGroup) return;

  // Add scanner filter group with current value mirrored
  const scannerVal = (document.getElementById('scanner-select') || {}).value || '';
  const scannerText = (document.getElementById('scanner-display-text') || {}).textContent || 'Любой сканер';

  // Inject selects — bind onchange to real selects
  drawerContent.querySelectorAll('select').forEach(sel => {
    const realSel = document.getElementById(sel.id);
    if (!realSel) return;
    // Mirror current value
    sel.value = realSel.value;
    // On change → update real select and filter
    sel.addEventListener('change', () => {
      realSel.value = sel.value;
      realSel.dispatchEvent(new Event('change'));
      _updateFabBadge();
    });
  });
}

// Update FAB badge with active filter count
function _updateFabBadge() {
  const fields = ['model-select','android-select','scanner-select','memory-select','buttons-select','handle-select','lte-select','frost-select'];
  const count = fields.filter(id => {
    const el = document.getElementById(id);
    return el && el.value;
  }).length;
  const badge = document.getElementById('fab-active-count');
  if (!badge) return;
  if (count > 0) {
    badge.textContent = count;
    badge.style.display = 'inline-block';
  } else {
    badge.style.display = 'none';
  }
}

// Touch swipe down to close drawer
(function() {
  let startY = 0;
  document.addEventListener('touchstart', e => {
    const drawer = document.getElementById('filter-drawer');
    if (drawer && drawer.classList.contains('open')) {
      startY = e.touches[0].clientY;
    }
  }, {passive: true});

  document.addEventListener('touchend', e => {
    const drawer = document.getElementById('filter-drawer');
    if (drawer && drawer.classList.contains('open')) {
      const diff = e.changedTouches[0].clientY - startY;
      if (diff > 80) closeFilterDrawer(); // swipe down 80px+ → close
    }
  }, {passive: true});
})();

