const STATS_KEY = 'm3_stats_v1';

function _loadStats() {
  try { return JSON.parse(localStorage.getItem(STATS_KEY) || '{}'); } catch { return {}; }
}
function _saveStats(s) {
  try { localStorage.setItem(STATS_KEY, JSON.stringify(s)); } catch {}
}
function _inc(obj, key, by=1) {
  obj[key] = (obj[key] || 0) + by;
}

// Записать просмотр модели
function trackModel(model) {
  if (!model) return;
  const s = _loadStats();
  if (!s.models) s.models = {};
  _inc(s.models, model);
  _saveStats(s);
}

// Записать просмотр SKU
function trackSKU(sku, model) {
  if (!sku) return;
  const s = _loadStats();
  if (!s.skus) s.skus = {};
  _inc(s.skus, `${sku}||${model||''}`);
  _saveStats(s);
}

// Записать применение фильтра
function trackFilter(field, value) {
  if (!value) return;
  const s = _loadStats();
  if (!s.filters) s.filters = {};
  _inc(s.filters, `${field}:${value}`);
  _saveStats(s);
}

// Записать конфигурацию (комбо фильтров)
function trackConfig(vals) {
  const parts = Object.entries(vals).filter(([k,v])=>v).map(([k,v])=>`${k}=${v}`);
  if (parts.length < 2) return;
  const key = parts.join(' · ');
  const s = _loadStats();
  if (!s.configs) s.configs = {};
  _inc(s.configs, key);
  _saveStats(s);
}

// Хук в filterSKU — трекинг фильтров и конфигов
const __origFilterSKU2 = window.filterSKU;
window.filterSKU = function() {
  if (typeof __origFilterSKU2 === 'function') __origFilterSKU2.apply(this, arguments);
  try {
    const vals = {
      model: (document.getElementById('model-select')||{}).value||'',
      android: (document.getElementById('android-select')||{}).value||'',
      scanner: (document.getElementById('scanner-select')||{}).value||'',
      memory: (document.getElementById('memory-select')||{}).value||'',
      buttons: (document.getElementById('buttons-select')||{}).value||'',
    };
    if (vals.model) trackModel(vals.model);
    Object.entries(vals).forEach(([k,v]) => { if(v) trackFilter(k,v); });
    trackConfig(vals);
  } catch(e) {}
};

// Хук — трекинг клика на карточку SKU
document.addEventListener('click', e => {
  const card = e.target.closest('.result-card');
  if (card) {
    const sku = card.dataset.sku || card.id.replace(/^card-\d+-/,'');
    const model = card.dataset.model || '';
    if (sku) trackSKU(sku, model);
  }
});

