let _statsOpen = false;
let _statsTab = 'models';

function toggleStatsWidget() {
  _statsOpen = !_statsOpen;
  const panel = document.getElementById('stats-panel');
  panel.classList.toggle('open', _statsOpen);
  if (_statsOpen) renderStatsTab(_statsTab);
}

function showStatsTab(tab) {
  _statsTab = tab;
  document.querySelectorAll('.stats-tab').forEach(t =>
    t.classList.toggle('active', t.getAttribute('onclick').includes(`'${tab}'`))
  );
  renderStatsTab(tab);
}

function renderStatsTab(tab) {
  const s = _loadStats();
  const el = document.getElementById('stats-content');
  if (!el) return;

  const topList = (obj, limit=10, labelFn) => {
    if (!obj || !Object.keys(obj).length)
      return '<div style="color:#bbb;font-size:12px;padding:12px 0;text-align:center">Ещё нет данных</div>';
    const sorted = Object.entries(obj).sort((a,b)=>b[1]-a[1]).slice(0, limit);
    const max = sorted[0][1];
    return sorted.map(([k,v]) => {
      const label = labelFn ? labelFn(k) : k;
      const pct = Math.round(v/max*100);
      return `<div style="margin-bottom:10px">
        <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:3px">
          <span style="font-weight:600;color:#1E2171;max-width:75%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${label}</span>
          <span style="color:#888">${v} раз</span>
        </div>
        <div style="height:5px;background:#f0f2f8;border-radius:3px">
          <div style="height:5px;width:${pct}%;background:#4F46E5;border-radius:3px;transition:width .3s"></div>
        </div>
      </div>`;
    }).join('');
  };

  if (tab === 'models') {
    el.innerHTML = `<div style="font-size:11px;color:#999;margin-bottom:10px">Топ выбранных моделей</div>` +
      topList(s.models);

  } else if (tab === 'skus') {
    el.innerHTML = `<div style="font-size:11px;color:#999;margin-bottom:10px">Топ просматриваемых SKU</div>` +
      topList(s.skus, 10, k => k.split('||')[0]);

  } else if (tab === 'filters') {
    el.innerHTML = `<div style="font-size:11px;color:#999;margin-bottom:10px">Популярные значения фильтров</div>` +
      topList(s.filters, 12, k => {
        const [field, val] = k.split(':');
        const labels = {model:'Модель',android:'Android',scanner:'Сканер',memory:'Память',buttons:'Кнопки'};
        return `${labels[field]||field}: ${val}`;
      });

  } else if (tab === 'configs') {
    el.innerHTML = `<div style="font-size:11px;color:#999;margin-bottom:10px">Популярные комбинации фильтров</div>` +
      topList(s.configs, 8, k => k.replace(/\w+=/g,'').replace(/·/g,'·'));
  }
}

function clearStats() {
  if (!confirm('Сбросить всю статистику?')) return;
  localStorage.removeItem(STATS_KEY);
  renderStatsTab(_statsTab);
}


