// =============================================
// INLINE STOCK POPUP per SKU card
// =============================================
let _inlineStockPopup = null;

function showInlineStock(event, sku) {
  event.stopPropagation();
  // Remove existing popup
  if (_inlineStockPopup) { _inlineStockPopup.remove(); _inlineStockPopup = null; }

  const uniqId = 'isp-' + Date.now();
  const popup = document.createElement('div');
  popup.className = 'inline-stock-popup';
  popup.innerHTML = `
    <div class="inline-stock-header">
      <span class="inline-stock-sku">${sku}</span>
      <span class="inline-stock-title">Наличие у дистрибьюторов</span>
      <button class="inline-stock-close" onclick="closeInlineStock()">✕</button>
    </div>
    <div class="inline-stock-body" id="${uniqId}">
      <div class="inline-stock-loading">⏳ Загрузка...</div>
    </div>`;
  document.body.appendChild(popup);
  _inlineStockPopup = popup;

  // Position near button — always visible on screen
  const btn = event.currentTarget;
  const rect = btn.getBoundingClientRect();
  const pw = 360, ph = 240;
  const margin = 12;
  // Horizontal: align to button left, clamp to viewport
  let left = rect.left;
  if (left + pw > window.innerWidth - margin) left = window.innerWidth - pw - margin;
  if (left < margin) left = margin;
  // Vertical: prefer below button, if no room go above
  let top = rect.bottom + 8;
  if (top + ph > window.innerHeight - margin) top = rect.top - ph - 8;
  if (top < margin) top = margin;
  popup.style.left = left + 'px';
  popup.style.top = top + 'px';

  // Close on outside click
  setTimeout(() => {
    document.addEventListener('click', _inlineStockOutside, {once: true, capture: true});
  }, 10);

  loadInlineStockData(sku, uniqId);
}

function _inlineStockOutside(e) {
  if (_inlineStockPopup && !_inlineStockPopup.contains(e.target)) {
    closeInlineStock();
  }
}

function closeInlineStock() {
  if (_inlineStockPopup) { _inlineStockPopup.remove(); _inlineStockPopup = null; }
  document.removeEventListener('click', _inlineStockOutside, {capture: true});
}

function loadInlineStockData(sku, bodyId) {
  const bodyEl = document.getElementById(bodyId);
  if (!bodyEl) return;
  const skuU = sku.toUpperCase().trim().replace(/[\s\-\/]/g,'');
  const norm = s => (s||'').toString().toUpperCase().trim().replace(/[\s\-\/]/g,'');
  const results = [];

  // Check Treolan — uses item.articul
  if (window.treolanLoaded && window.TREOLAN_DATA) {
    let row = window.TREOLAN_DATA.find(r => norm(r.articul) === skuU);
    if (!row) row = window.TREOLAN_DATA.find(r => Object.values(r).some(v => typeof v==='string' && norm(v)===skuU));
    if (row) {
      results.push({dist:'Treolan', color:'#3b82f6', qty: parseInt(row.stock||row.quantity||0)||0, transit: parseInt(row.transit||0)||0});
    } else {
      results.push({dist:'Treolan', color:'#3b82f6', qty:0, transit:0, notFound:true});
    }
  }

  // Check OCS — uses item.partNumber or item.itemId, qty in item.stock[].quantity
  if (window.ocsLoaded && window.OCS_DATA) {
    const row = window.OCS_DATA.find(r => {
      const a = norm(r.partNumber || r.itemId || r.articul || r['Артикул'] || '');
      return a === skuU;
    });
    if (row) {
      const qty = (row.stock || []).reduce((s, l) => s + (l.quantity || 0), 0);
      const transit = (row.transit || []).reduce((s, l) => s + (l.quantity || 0), 0);
      results.push({dist:'OCS', color:'#10b981', qty, transit});
    } else {
      results.push({dist:'OCS', color:'#10b981', qty:0, transit:0, notFound:true});
    }
  }

  // Check M3 Stock — detect articul and stock keys from headers
  if (window.m3StockLoaded && window.M3_STOCK_DATA) {
    const headers = window._m3StockHeaders || [];
    const artKey = headers.find(h => /артикул|sku|artic|part/i.test(h)) || headers[0];
    const stockKey = headers.find(h => /остат|склад|stock|наличи|кол/i.test(h)) || headers[2];
    const row = window.M3_STOCK_DATA.find(r => norm(artKey ? r[artKey] : Object.values(r)[0] || '') === skuU);
    if (row) {
      const qty = parseInt(stockKey ? row[stockKey] : Object.values(row).find((v,i)=>i>0&&!isNaN(parseInt(v)))) || 0;
      results.push({dist:'M3 Stock', color:'#f59e0b', qty, transit:0});
    } else {
      results.push({dist:'M3 Stock', color:'#f59e0b', qty:0, transit:0, notFound:true});
    }
  }

  if (!results.length) {
    bodyEl.innerHTML = '<div class="isp-no-data">Данные не загружены. Откройте меню «Сток» для предзагрузки данных.</div>';
    return;
  }

  let html = '<table class="isp-table"><thead><tr><th>Дистрибьютор</th><th>На складе</th><th>В пути</th></tr></thead><tbody>';
  results.forEach(r => {
    const badge = r.qty > 0
      ? `<span class="isp-badge isp-in">${r.qty} шт.</span>`
      : `<span class="isp-badge isp-out">Нет</span>`;
    const transitBadge = r.transit > 0 ? `<span class="isp-transit">${r.transit}</span>` : '—';
    html += `<tr><td><span class="isp-dot" style="background:${r.color}"></span><span class="isp-dist-name">${r.dist}</span></td><td>${badge}</td><td>${transitBadge}</td></tr>`;
  });
  html += '</tbody></table>';
  bodyEl.innerHTML = html;
}

