const ACCW_SVG=(inner)=>'<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">'+inner+'</svg>';
const ACCW_ICONS={
device:ACCW_SVG('<rect x="22" y="8" width="20" height="34" rx="4"/><line x1="28" y1="37" x2="36" y2="37"/><path d="M14 42h36l-4 12H18z"/>'),
batt:ACCW_SVG('<rect x="22" y="12" width="20" height="40" rx="4"/><rect x="28" y="6" width="8" height="6" rx="2"/><path d="M34 22l-7 14h9l-6 12"/>'),
both:ACCW_SVG('<rect x="8" y="12" width="16" height="28" rx="3"/><path d="M4 42h24l-3 9H7z"/><rect x="40" y="16" width="17" height="30" rx="4"/><path d="M50 24l-4 9h6l-4 9"/>'),
none:ACCW_SVG('<circle cx="32" cy="32" r="22"/><line x1="17" y1="47" x2="47" y2="17"/>'),
chg:ACCW_SVG('<rect x="14" y="40" width="36" height="12" rx="4"/><rect x="24" y="14" width="16" height="26" rx="3"/><path d="M28 8v6M36 8v6"/>'),
usb:ACCW_SVG('<rect x="10" y="26" width="44" height="14" rx="7"/><rect x="17" y="31" width="30" height="4" rx="2"/><path d="M32 40v12"/>'),
eth:ACCW_SVG('<rect x="18" y="16" width="28" height="26" rx="3"/><path d="M26 42v8M32 42v8M38 42v8"/><line x1="24" y1="23" x2="24" y2="28"/><line x1="30" y1="23" x2="30" y2="28"/><line x1="36" y1="23" x2="36" y2="28"/><line x1="42" y1="23" x2="42" y2="28"/>'),
slot1:ACCW_SVG('<rect x="24" y="10" width="16" height="30" rx="3"/><path d="M16 42h32l-4 12H20z"/>'),
slotN:ACCW_SVG('<rect x="8" y="14" width="10" height="22" rx="2"/><rect x="22" y="14" width="10" height="22" rx="2"/><rect x="36" y="14" width="10" height="22" rx="2"/><rect x="50" y="14" width="6" height="22" rx="2"/><path d="M4 40h56l-4 12H8z"/>'),
protect:ACCW_SVG('<rect x="20" y="10" width="24" height="42" rx="5"/><path d="M14 12c-3 4-3 8 0 12M50 12c3 4 3 8 0 12M14 40c-3 4-3 8 0 12M50 40c3 4 3 8 0 12"/>'),
screen:ACCW_SVG('<rect x="18" y="8" width="28" height="48" rx="4"/><path d="M24 14l16 16M24 26l10 10"/>'),
grip:ACCW_SVG('<rect x="16" y="8" width="32" height="20" rx="4"/><path d="M28 28v8c0 3 2 4 4 4s4-1 4-4v-8"/><path d="M30 40l-4 16h12l-4-16"/>'),
strap:ACCW_SVG('<rect x="22" y="10" width="20" height="34" rx="4"/><path d="M24 48c-6 4-6 8 8 8s14-4 8-8"/>'),
wear:ACCW_SVG('<rect x="20" y="20" width="24" height="18" rx="3"/><path d="M20 26H8m48 0H44M8 26c-4 3-4 6 0 9m48-9c4 3 4 6 0 9"/>'),
vehicle:ACCW_SVG('<path d="M10 40h22v-16h10l8 10v6"/><circle cx="18" cy="48" r="5"/><circle cx="42" cy="48" r="5"/><path d="M54 18v26M54 44h-8"/>'),
check:ACCW_SVG('<path d="M12 34l14 14 26-30"/>')};

/* Классификация аксессуара по артикулу + описанию */
function accwClassify(acc){
const s=(acc.sku||'').toUpperCase(),d=(acc.description||'').toUpperCase();
if(s.includes('VCRD')||s.includes('FCRD')||d.includes('VEHICLE')||d.includes('FORKLIFT')||s.includes('-BRKT'))return{group:'vehicle'};
const m=s.match(/-(\d+)CRD-([A-Z0-9]*)/);
if(m){const slots=parseInt(m[1],10)||1;const suf=m[2]||'';let comm='chg';
if(suf[0]==='E'||d.includes('ETHERNET'))comm='eth';
else if((suf.length>1&&suf.includes('U'))||d.includes('USB')||d.includes('TYPE-C'))comm='usb';
return{group:'cradle',slots,comm};}
const b=s.match(/-(\d+)BC-/);if(b)return{group:'battcharger',slots:parseInt(b[1],10)||1};
if(s.includes('-BATT'))return{group:'battery'};
if(s.includes('-SCPR')||d.includes('SCREEN PROT'))return{group:'screen'};
if(s.includes('-BOOT')||s.includes('-CASE')||s.includes('BUMP')||d.includes('BUMPER')||d.includes('PROTECTIVE'))return{group:'protect'};
if(s.includes('-TRIG')||s.includes('-GRIP')||s.includes('-GUN')||d.includes('TRIGGER')||d.includes('GUN GRIP')||d.includes('GUN HANDLE')||d.includes('PISTOL')||d.includes('SCAN HANDLE'))return{group:'grip'};
if(s.includes('WEWM')||s.includes('WWMS')||d.includes('ARM MOUNT')||d.includes('WEARABLE MOUNT'))return{group:'wear'};
if(s.includes('-STRP')||d.includes('STRAP'))return{group:'strap'};
/* UL30: заряжается только через снап-адаптер, БП подтягивается автоматически */
if(s==='UL30-SNAP-C0A')return{group:'device_psu'};
if(s==='UNIV-PWSP-V00'&&(accwState.model||'').toUpperCase()==='UL30')return{group:'power'};
/* PSU с кабелем для прямой зарядки ТСД - только конкретные модели */
if(s==='SL20-PWSP-CEU'||s==='SL2K-PWSP-CEU'||s==='SM30-PWSP-CEU'||s==='WR10-PWSP-CEU'||s==='WR15-PWSP-CEU'||s==='WD10-PWSP-CEU'||s==='UNIV-PWSP-V00')return{group:'device_psu'};
/* Остальные PWSP - это блоки питания для кредлов */
if(s.includes('-PWSP')||s.includes('-CABL')||d.includes('POWER SUPPLY')||d.includes('ADAPTER')||d.includes('CABLE'))return{group:'power'};
return{group:'other'};}

/* Количество в упаковке: доп. суффикс -S10/-S50 (4-й сегмент SKU), код ремешка STRP-x10, либо описание (10EA/10PCS) */
function accwStripPack(s){const p=s.split('-');
if(p.length>=4&&/^S\d{2}$/.test(p[p.length-1]))return p.slice(0,-1).join('-');
return s;}
function accwPackQty(acc){
const s=(acc.sku||'').toUpperCase(),d=(acc.description||'').toUpperCase();
if(accwStripPack(s)!==s){const n=parseInt(s.slice(-2),10);if(n>1)return n;}
let m=s.match(/-STRP-[A-Z](\d+)/);if(m&&parseInt(m[1],10)>1)return parseInt(m[1],10);
m=d.match(/(\d+)\s*(?:EA|PCS?|SET)/);if(m&&parseInt(m[1],10)>1)return parseInt(m[1],10);
return 1;}
function accwPackSuffix(acc){const n=accwPackQty(acc);
return n>1?' — '+accwT('pack').replace('{n}',n):' — '+accwT('pack1');}

/* Извлеки количество ТСД и АКБ из описания кредла */
function accwParseCradleDesc(desc){
const d=(desc||'').toUpperCase();
let devices=0,batteries=0;
// Pattern: "4xdevice" или "for 4x device" или "1xSM30" или "4x SL20K"
const devMatch=d.match(/(?:for\s+)?(\d+)x\s*(?:device|[A-Z]+\d+)/i);if(devMatch)devices=parseInt(devMatch[1],10);
// Pattern: "4xbatteries" или "1x spare battery" - ловит обе формы
const battMatch=d.match(/(\d+)x(?:.*?)?batt/i);if(battMatch)batteries=parseInt(battMatch[1],10);
// Fallback: если есть слоты и всё равно не нашли ТСД
if(!devices&&d.includes('1-slot'))devices=1;
if(!devices&&d.includes('2-slot'))devices=1;
if(!devices&&d.includes('8-slot'))devices=4;
if(!devices&&d.includes('5-slot'))devices=2;
return{devices,batteries};}


/* Русские КОРОТКИЕ подписи для карточек - понятные, без лишних слов */
function accwLabel(acc,cls){
const s=(acc.sku||'').toUpperCase(),d=(acc.description||'').toUpperCase();
if(cls.group==='cradle'){
const{devices,batteries}=accwParseCradleDesc(acc.description);
if(devices>0){
let nm='Кредл на '+devices+' ТСД';
if(batteries>0)nm+=' + '+batteries+' АКБ';
return nm;
}
// Fallback если парсинг не сработал
const slots=cls.slots||1;
return 'Кредл на '+slots+' слотов';}
if(cls.group==='battcharger'){
const slots=cls.slots||1;
return 'Зарядка АКБ на '+slots+' '+(slots===1?'шт':'шт');}
if(cls.group==='battery'){
const base=accwStripPack(s);
const letter=(base.match(/-BATT-([A-Z])/)||[])[1];
const siblings=(accwState.groups.battery||[]);
const letters=new Set(siblings.map(x=>(accwStripPack(x.acc.sku.toUpperCase()).match(/-BATT-([A-Z])/)||[])[1]).filter(Boolean));
const map={S:'стандартная',E:'увеличенная',F:'морозостойкая',X:'увеличенная'};
const suffix=letters.size>1?' ('+map[letter]+')':'';
return 'АКБ'+suffix+accwPackSuffix(acc);}
if(cls.group==='device_psu'){if(s==='UL30-SNAP-C0A')return'Снап-адаптер с блоком питания';return'Блок питания с кабелем';}
if(cls.group==='protect'){if(s.includes('-BOOT'))return'Чехол';if(s.includes('CASE'))return'Чехол';return'Защита';}
if(cls.group==='screen')return'Защитная плёнка'+accwPackSuffix(acc);
if(cls.group==='grip')return'Пистолетная ручка';
if(cls.group==='strap')return'Ремешок'+accwPackSuffix(acc);
if(cls.group==='wear')return'Крепление на запястье';
if(cls.group==='vehicle'){if(s.includes('FCRD'))return'Крепление на погрузчик';if(s.includes('VCRD'))return'Кредл для авто';return'Крепление';}
return acc.description||acc.sku;}

const accwState={model:'',items:[],groups:{},steps:[],idx:0,answers:{},applied:{},autoMap:{},active:false};

function accwRequired(sku){const up=(sku||'').toUpperCase();
return ACC_REQUIRED[up+'::'+accwState.model]||ACC_REQUIRED[up+'::'+up.split('-')[0]]||null;}

/* Применить/снять артикул: через чекбокс списка, если он есть */
function accwSet(sku,on){const up=(sku||'').toUpperCase();
const item=document.querySelector('#accessoriesList .acc-item[data-sku="'+up+'"]');
if(item){const cb=item.querySelector('input[type=checkbox]');
if(cb&&cb.checked!==on){cb.checked=on;cb.dispatchEvent(new Event('change'));}}
else{updateAccessorySelection(up,on);}
}

function accwApplyStep(stepId,skus){
const prev=accwState.applied[stepId]||[];
prev.forEach(sk=>{if(!skus.includes(sk)){accwSet(sk,false);accwDropAuto(sk);}});
skus.forEach(sk=>{accwSet(sk,true);const req=accwRequired(sk);
if(req){(accwState.autoMap[req]=accwState.autoMap[req]||new Set()).add(sk);accwSet(req,true);}});
accwState.applied[stepId]=skus.slice();
accwRenderPicked();updateTotalPrice();}

function accwDropAuto(parentSku){for(const req in accwState.autoMap){const set=accwState.autoMap[req];
if(set.delete(parentSku)&&set.size===0){delete accwState.autoMap[req];accwSet(req,false);}}}

/* Построение шагов из доступных групп аксессуаров модели */
function accwBuildSteps(){
const g=accwState.groups,steps=[];
const hasCradle=(g.cradle||[]).length>0,hasBC=(g.battcharger||[]).length>0,hasPSU=(g.device_psu||[]).length>0;
if(hasCradle||hasBC||hasPSU){
const opts=[];
if(hasCradle||hasPSU)opts.push({v:'device',label:accwT('opt_device'),sub:accwT('opt_device_sub'),icon:'device'});
if(hasBC)opts.push({v:'battery',label:accwT('opt_batt'),sub:accwT('opt_batt_sub'),icon:'batt'});
if((hasCradle||hasPSU)&&hasBC)opts.push({v:'both',label:accwT('opt_both'),icon:'both'});
opts.push({v:'none',label:accwT('opt_none'),icon:'none'});
steps.push({id:'charge',title:accwT('q_charge'),hint:accwT('q_charge_hint'),options:opts,
apply:a=>{
if(a.charge==='battery'||a.charge==='none'){accwApplyStep('cradle',[]);accwApplyStep('device_psu',[]);}
if(a.charge==='device'||a.charge==='none')accwApplyStep('battcharger',[]);
if(a.charge==='both'){/* оба остаются, шаги покажут выбор для каждого */}
}});
}
if(hasCradle||hasPSU){
const allCradles=(g.cradle||[]),allPSU=(g.device_psu||[]);
const allDeviceOpts=allCradles.concat(allPSU);
steps.push({id:'device_pick',title:'Выбери способ зарядки ТСД',
when:a=>(a.charge==='device'||a.charge==='both')&&allDeviceOpts.length>0,
optionsFn:a=>{
return allDeviceOpts.map(x=>{
const isCradle=x.cls.group==='cradle';
return{
v:x.acc.sku,
label:accwLabel(x.acc,x.cls),
photo:accwPhoto(x.acc.sku),
sub:x.acc.sku,
icon:isCradle?'cradle':'psu'
};}).concat([{v:'__none',label:accwT('opt_no'),icon:'none'}]);
},
apply:a=>{
const chosen=a.device_pick;
if(chosen==='__none'){accwApplyStep('cradle',[]);accwApplyStep('device_psu',[]);}
else{
const item=allDeviceOpts.find(x=>x.acc.sku===chosen);
if(item){
if(item.cls.group==='cradle'){accwApplyStep('cradle',[chosen]);accwApplyStep('device_psu',[]);}
else{accwApplyStep('device_psu',[chosen]);accwApplyStep('cradle',[]);}
}}}});
}
if(hasBC){
steps.push({id:'bslots',title:accwT('q_bslots'),
when:a=>a.charge==='battery'||a.charge==='both',
optionsFn:()=>{const sl=[...new Set(g.battcharger.map(x=>x.cls.slots))].sort((x,y)=>x-y);
return sl.map(n=>{const v=g.battcharger.find(x=>x.cls.slots===n);
return{v:String(n),label:n+' '+(n===1?accwT('opt_slot1'):accwT('opt_slots')),photo:accwPhoto(v.acc.sku),icon:n===1?'slot1':'slotN',sub:v.acc.sku};});},
apply:a=>{const v=g.battcharger.find(x=>String(x.cls.slots)===a.bslots);
if(v)accwApplyStep('battcharger',[v.acc.sku]);}});
}
const itemStep=(id,groupKey,title,hint,icon)=>{
if(!(g[groupKey]||[]).length)return;
steps.push({id,title,hint,
optionsFn:()=>g[groupKey].map(x=>({v:x.acc.sku,label:accwLabel(x.acc,x.cls),photo:accwPhoto(x.acc.sku),icon,sub:x.acc.sku}))
.concat([{v:'__none',label:accwT('opt_no'),icon:'none'}]),
apply:a=>accwApplyStep(id,a[id]==='__none'?[]:[a[id]])});};
itemStep('battery','battery',accwT('q_spare'),accwT('q_spare_hint'),'batt');
itemStep('protect','protect',accwT('q_protect'),'','protect');
itemStep('screen','screen',accwT('q_screen'),'','screen');
itemStep('grip','grip',accwT('q_grip'),accwT('q_grip_hint'),'grip');
itemStep('strap','strap',accwT('q_strap'),'','strap');
itemStep('wear','wear',accwT('q_wear'),'','wear');
itemStep('vehicle','vehicle',accwT('q_vehicle'),'','vehicle');
return steps;}

/* Гарантированные SKU прямой зарядки ТСД по модели.
   Для UL30 карточка — снап-адаптер; UNIV-PWSP-V00 подтянется через ACC_REQUIRED. */
const DEVICE_PSU_BY_MODEL={
UL30:['UL30-SNAP-C0A'],
SL20:['SL20-PWSP-CEU'],SL20P:['SL20-PWSP-CEU'],
SL20K:['SL2K-PWSP-CEU'],SL2K:['SL2K-PWSP-CEU'],
SM30:['SM30-PWSP-CEU'],
WR10:['WR10-PWSP-CEU'],WR15:['WR10-PWSP-CEU'],
WD10:['WD10-PWSP-CEU'],
SM20:['UNIV-PWSP-V00'],SM24:['UNIV-PWSP-V00'],
US20:['UNIV-PWSP-V00'],US30:['UNIV-PWSP-V00']};

function initAccWizard(modelCode,compAccs){
const host=$('accWizard'),toggle=$('accListToggle'),list=$('accessoriesList');
accwState.model=modelCode;accwState.answers={};accwState.applied={};accwState.autoMap={};accwState.idx=0;
const seen=new Set((compAccs||[]).map(s=>String(s).toUpperCase()));
const extra=(DEVICE_PSU_BY_MODEL[(modelCode||'').toUpperCase()]||[])
  .filter(s=>!seen.has(s)&&(ACCMAP[s]||ACCESSORIES_DB.some(a=>a.sku.toUpperCase()===s)));
compAccs=(compAccs||[]).concat(extra);
accwState.items=(compAccs||[]).map(sk=>{const acc=ACCMAP[sk]||ACCESSORIES_DB.find(a=>a.sku.toUpperCase()===sk);
return acc?{acc,cls:accwClassify(acc)}:null;}).filter(Boolean);
accwState.groups={};accwState.items.forEach(x=>{(accwState.groups[x.cls.group]=accwState.groups[x.cls.group]||[]).push(x);});
if(!accwState.items.length){host.innerHTML='';toggle.style.display='none';list.style.display='block';accwState.active=false;return;}
accwState.steps=accwBuildSteps();
accwState.active=true;
$('accListToggleLabel').textContent=accwT('list_toggle')+' ('+accwState.items.length+')';
toggle.style.display='flex';toggle.classList.remove('open');
list.style.display='none';
accwRenderStep();}

function toggleAccList(){const list=$('accessoriesList'),toggle=$('accListToggle');
const show=list.style.display==='none';
list.style.display=show?'block':'none';toggle.classList.toggle('open',show);}

function accwActiveSteps(){return accwState.steps.filter(s=>!s.when||s.when(accwState.answers));}

function accwRenderStep(){
const host=$('accWizard'),steps=accwActiveSteps();
if(accwState.idx>=steps.length){accwRenderDone();return;}
const st=steps[accwState.idx];
const opts=st.optionsFn?st.optionsFn(accwState.answers):st.options;
let html='<div class="accw-progress">'+steps.map((s,i)=>'<i class="'+(i<accwState.idx?'done':i===accwState.idx?'now':'')+'"></i>').join('')+'</div>';
html+='<div class="accw-eyebrow">'+accwT('step')+' '+(accwState.idx+1)+' / '+steps.length+'</div>';
html+='<div class="accw-title">'+st.title+'</div>';
if(st.hint)html+='<div class="accw-hint">'+st.hint+'</div>';
html+='<div class="accw-options">'+opts.map(o=>{
const sel=accwState.answers[st.id]===o.v?' selected':'';
const visual=o.photo?'<span class="accw-ph"><img src="'+o.photo+'" alt="" loading="lazy"></span>':'<span class="accw-ico">'+(ACCW_ICONS[o.icon]||ACCW_ICONS.none)+'</span>';
return '<button type="button" class="accw-opt'+sel+'" data-v="'+o.v+'">'+visual+'<span class="accw-lbl">'+o.label+'</span>'+(o.sub?'<span class="accw-sub">'+o.sub+'</span>':'')+'</button>';
}).join('')+'</div>';
html+='<div class="accw-nav"><button type="button" class="accw-btn ghost" id="accwBack"'+(accwState.idx===0?' style="visibility:hidden"':'')+'>'+accwT('btn_back')+'</button>'
+'<button type="button" class="accw-btn ghost" id="accwSkip">'+accwT('opt_skip')+'</button></div>';
html+='<div class="accw-picked" id="accwPicked"></div>';
host.innerHTML=html;
host.querySelectorAll('.accw-opt').forEach(b=>b.addEventListener('click',()=>{
accwState.answers[st.id]=b.dataset.v;
if(st.apply)st.apply(accwState.answers);
host.querySelectorAll('.accw-opt').forEach(x=>x.classList.toggle('selected',x===b));
setTimeout(()=>{accwState.idx++;accwRenderStep();},200);}));
$('accwBack').addEventListener('click',()=>{accwState.idx=Math.max(0,accwState.idx-1);accwRenderStep();});
$('accwSkip').addEventListener('click',()=>{accwState.idx++;accwRenderStep();});
accwRenderPicked();}

function accwRenderDone(){
const host=$('accWizard');
host.innerHTML='<div class="accw-progress">'+accwActiveSteps().map(()=>'<i class="done"></i>').join('')+'</div>'
+'<div class="accw-done"><div class="accw-done-ico">'+ACCW_ICONS.check+'</div>'
+'<div class="accw-title">'+accwT('done_title')+'</div>'
+'<div class="accw-hint">'+accwT('done_text')+'</div>'
+'<div class="accw-done-btns">'
+'<button type="button" class="accw-btn primary" onclick="addSKUToSpecification()">'+accwT('btn_add')+'</button>'
+'<button type="button" class="accw-btn ghost" id="accwRestart">'+accwT('btn_restart')+'</button>'
+'</div></div><div class="accw-picked" id="accwPicked"></div>';
$('accwRestart').addEventListener('click',()=>{
Object.keys(accwState.applied).forEach(id=>accwApplyStep(id,[]));
accwState.answers={};accwState.idx=0;accwRenderStep();});
accwRenderPicked();}

function accwRenderPicked(){
const el=document.getElementById('accwPicked');if(!el)return;
const sel=(currentSelection&&currentSelection.accessories)||[];
if(!sel.length){el.innerHTML='';return;}
const auto=new Set(Object.keys(accwState.autoMap).map(s=>s.toUpperCase()));
el.innerHTML='<div class="accw-picked-title">'+accwT('picked')+': '+sel.length+'</div>'
+sel.map(sk=>{const up=sk.toUpperCase();const acc=ACCMAP[up]||ACCESSORIES_DB.find(a=>a.sku.toUpperCase()===up);
const cls=acc?accwClassify(acc):{group:'other'};
const nm=acc?accwLabel(acc,cls):up;
return '<span class="accw-chip'+(auto.has(up)?' auto':'')+'" title="'+(acc&&acc.description?acc.description.replace(/"/g,'&quot;'):'')+'">'
+nm+'<b>'+up+'</b>'+(auto.has(up)?'<i>'+accwT('auto_badge')+'</i>':'')+'</span>';}).join('');}
